from __future__ import (absolute_import, division, print_function)
__metaclass__ = type

import errno
import math
import re
import time


def get_sysctl(module, prefixes):
    try:
        sysctl_cmd = module.get_bin_path('sysctl')
        if not sysctl_cmd:
            module.warn('Unable to read sysctl: Unable to find sysctl')
            return {}
        cmd = [sysctl_cmd]
        cmd.extend(prefixes)
        rc, out, err = module.run_command(cmd)
    except (IOError, OSError) as e:
        module.warn('Unable to read sysctl: %s' % e)
        return {}
    if rc != 0:
        module.warn('Unable to read sysctl: %s' % (err or out or 'exit code %s' % rc))
        return {}

    sysctl = {}
    last_key = None
    for line in out.splitlines():
        if not line:
            continue
        if line[0].isspace() and last_key is not None:
            sysctl[last_key] += '\n' + line
            continue
        try:
            key, value = re.split(r'\s*=\s*|:\s*|\s+', line, maxsplit=1)
            if not key:
                raise ValueError('empty sysctl key')
        except ValueError as e:
            module.warn('Unable to split sysctl line (%s): %s' % (line, e))
            last_key = None
            continue
        sysctl[key] = value.strip()
        last_key = key

    return sysctl


